//! The build script of the conformance crate.
//!
//! WHAT: it reads `vectors/index.json`, copies every vector into the
//! output directory and generates the list of the embedded vectors.
//!
//! WHY: the vectors are **data**, and the crate that replays them must
//! work without a file system — the rule of
//! `docs/design/BUILD-CONTRACT.md` § 1.2 holds for every crate of `core/`.
//! The build script is the only place that reads the files, and the files
//! stay in the repository so that a shell can replay them through its
//! bridge.
//!
//! The generated file is written by this script and is never edited by
//! hand.
//!
//! WHY the script returns a `Result` and does not abort: a build script has
//! no caller that could receive an error value — the only way to report a
//! failure is to end the build with one. Returning the error lets cargo
//! print it with the file and the line.

use std::env;
use std::error::Error;
use std::fs;
use std::path::Path;

/// The entry of the index of the vectors.
struct IndexEntry {
    id: String,
    file: String,
}

fn main() -> Result<(), Box<dyn Error>> {
    let manifest = env::var("CARGO_MANIFEST_DIR")?;
    let vectors = Path::new(&manifest).join("vectors");
    let out_dir = env::var("OUT_DIR")?;

    println!("cargo:rerun-if-changed=vectors/index.json");
    println!("cargo:rerun-if-changed=vectors");

    let target = Path::new(&out_dir).join("vectors");
    // The directory of a previous build may still exist; it is removed, but
    // a missing directory is not an error.
    let _ = fs::remove_dir_all(&target);
    fs::create_dir_all(&target)?;

    let mut generated = String::new();
    generated.push_str("// @generated by build.rs — do not edit.\n");

    // The corpus of the base itself.
    let index = fs::read_to_string(vectors.join("index.json"))?;
    let entries = parse_index(&index);
    generated.push_str(
        "/// Every vector of the corpus of the base: the identifier and the content of the file.\npub const VECTOR_FILES: &[(&str, &str)] = &[\n",
    );
    generated.push_str(&generate(&entries, &vectors, &target)?);
    generated.push_str("];\n");

    // The corpus of the web shell — the reference behaviour of the
    // TypeScript implementation.
    let web_shell = vectors.join("web-shell");
    if web_shell.join("index.json").exists() {
        let index = fs::read_to_string(web_shell.join("index.json"))?;
        let entries = parse_index(&index);
        generated.push_str(
            "/// Every vector of the corpus of the web shell.\npub const WEB_SHELL_VECTOR_FILES: &[(&str, &str)] = &[\n",
        );
        generated.push_str(&generate(&entries, &web_shell, &target)?);
        generated.push_str("];\n");
    }
    fs::write(Path::new(&out_dir).join("vectors_generated.rs"), generated)?;
    Ok(())
}

/// Generates the list of the embedded vectors.
fn generate(
    entries: &[IndexEntry],
    source: &Path,
    target: &Path,
) -> Result<String, std::io::Error> {
    let mut generated = String::new();
    for entry in entries {
        let path = source.join(&entry.file);
        println!("cargo:rerun-if-changed={}", path.display());
        let content = fs::read_to_string(&path)?;
        let file_name = entry.file.replace('/', "_");
        fs::write(target.join(&file_name), &content)?;
        generated.push_str("    (\n        \"");
        generated.push_str(&entry.id);
        generated.push_str("\",\n        include_str!(concat!(env!(\"OUT_DIR\"), \"/vectors/");
        generated.push_str(&file_name);
        generated.push_str("\"))),\n");
    }
    Ok(generated)
}

/// Reads the entries of the index.
///
/// WHY: the index is a small, fixed JSON document. The build script reads it
/// without a JSON library, so that the build of the crate needs no
/// dependency at all.
fn parse_index(index: &str) -> Vec<IndexEntry> {
    let mut entries = Vec::new();
    let mut id: Option<String> = None;
    let mut file: Option<String> = None;

    for line in index.lines() {
        let trimmed = line.trim();
        if let Some(rest) = trimmed.strip_prefix("\"id\":") {
            id = read_string(rest);
            file = None;
        } else if let Some(rest) = trimmed.strip_prefix("\"file\":") {
            file = read_string(rest);
        }
        if let (Some(entry_id), Some(entry_file)) = (id.clone(), file.clone()) {
            entries.push(IndexEntry {
                id: entry_id,
                file: entry_file,
            });
            id = None;
            file = None;
        }
    }
    entries
}

/// Reads a JSON string value.
fn read_string(text: &str) -> Option<String> {
    let start = text.find('"')? + 1;
    let rest = text.get(start..)?;
    let end = rest.find('"')?;
    Some(rest.get(..end)?.to_string())
}
